set-variable.value:
@{
        var supplied = context.Request.Headers.GetValueOrDefault("x-correlation-id", string.Empty);
        return System.Text.RegularExpressions.Regex.IsMatch(supplied, @"\A[A-Za-z0-9][A-Za-z0-9._-]{0,127}\z")
            ? supplied : context.RequestId.ToString();
    }

@{
                      var attachments = context.Request.Body.As<JObject>(preserveContent: true)["attachments"] as JArray;
                      return attachments == null ? 0 : attachments.Count;
                  }

@{
                      var attachments = context.Request.Body.As<JObject>(preserveContent: true)["attachments"] as JArray;
                      if (attachments == null)
                      {
                return string.Empty;
                      }

              if (attachments.Count > 3)
                      {
                return "The attachments array contains " + attachments.Count + " items; at most 3 are allowed.";
              }

              for (var index = 0; index < attachments.Count; index++)
              {
                var attachment = attachments[index] as JObject;
                          if (attachment == null)
                          {
                  return "Attachment at index " + index + " must be a JSON object.";
                          }

                          var fileId = (string)attachment["file_id"] ?? string.Empty;
                          var name = (string)attachment["name"] ?? string.Empty;
                if (string.IsNullOrWhiteSpace(fileId))
                {
                  return "Attachment at index " + index + " is missing file_id.";
                }
                if (!fileId.StartsWith("file-", StringComparison.Ordinal)
                  && !fileId.StartsWith("assistant-", StringComparison.Ordinal))
                {
                  return "Attachment at index " + index + " has an invalid file_id; use the id returned by the attachment upload API.";
                }
                if (fileId.Length > 200)
                {
                  return "Attachment at index " + index + " has a file_id longer than 200 characters.";
                }
                if (string.IsNullOrWhiteSpace(name))
                {
                  return "Attachment at index " + index + " is missing name.";
                }
                if (name.Length > 255)
                {
                  return "Attachment at index " + index + " has a name longer than 255 characters.";
                }

                var lowerName = name.ToLowerInvariant();
                if (!lowerName.EndsWith(".jpg") && !lowerName.EndsWith(".jpeg")
                  && !lowerName.EndsWith(".png") && !lowerName.EndsWith(".webp")
                  && !lowerName.EndsWith(".gif") && !lowerName.EndsWith(".pdf"))
                {
                  return "Attachment at index " + index + " has an unsupported filename extension; use JPEG, PNG, WebP, GIF, or PDF.";
                }
              }

              return string.Empty;
                  }

@{
        var token = ((string)context.Variables["commerceToken"]).AsJwt();
        return token == null ? string.Empty : token.Issuer;
    }

@{
        if ((bool)context.Variables["anonymousCaller"] || !(bool)context.Variables["customerToken"]) { return true; }
        var token = (Jwt)context.Variables["commerceJwt"];
        var scope = (string)context.Variables["customerRequiredScope"];
        var policy = (string)context.Variables["customerPolicy"];
        return !string.IsNullOrWhiteSpace(token.Subject)
            && (scope == "__not-configured__" || (token.Claims.ContainsKey("scp") && token.Claims["scp"].Any(value => value.Split((char)32).Contains(scope))))
            && (policy == "__not-configured__" || (token.Claims.ContainsKey("{{b2c-policy-claim}}") && token.Claims["{{b2c-policy-claim}}"].Any(value => string.Equals(value, policy, StringComparison.Ordinal))));
    }

inbound.set-body:
@{
        var assistantInstructions = (string)context.Variables["assistantInstructions"];
        var toolHeaders = new JObject
        {
            ["x-correlation-id"] = (string)context.Variables["correlationId"]
        };
        if (!(bool)context.Variables["anonymousCaller"])
        {
            toolHeaders["Authorization"] = (string)context.Variables["commerceTransportAuthorization"];
        }
        var deviceToken = (string)context.Variables["commerceDeviceToken"];
        if (!string.IsNullOrWhiteSpace(deviceToken))
        {
            toolHeaders["DeviceToken"] = deviceToken;
        }

        var tools = new JArray
        {
            new JObject
            {
                ["type"] = "mcp",
                ["server_label"] = "{{mcp-server-label}}",
                ["server_url"] = "{{mcp-server-url}}",
                ["require_approval"] = "never",
                ["headers"] = toolHeaders
            }
        };
            tools.Add(new JObject
        {
              ["type"] = "mcp",
              ["server_label"] = "foundry-iq-knowledge",
              ["server_url"] = "{{foundry-iq-mcp-url}}",
              ["require_approval"] = "never",
              ["allowed_tools"] = new JArray("knowledge_base_retrieve"),
              ["headers"] = new JObject
            {
                ["Authorization"] = "Bearer " + (string)context.Variables["searchAccessToken"],
                ["x-correlation-id"] = (string)context.Variables["correlationId"]
              }
            });

        var content = new JArray();
        var message = (string)context.Variables["message"];
        if (!string.IsNullOrWhiteSpace(message))
        {
          content.Add(new JObject
          {
            ["type"] = "input_text",
            ["text"] = message
          });
        }

        var requestBody = context.Request.Body.As<JObject>(preserveContent: true);
        var attachments = requestBody["attachments"] as JArray;
        if (attachments != null)
        {
          foreach (var token in attachments)
          {
            var attachment = (JObject)token;
            var fileId = (string)attachment["file_id"];
            var name = (string)attachment["name"];
            var lowerName = name.ToLowerInvariant();
            if (!lowerName.EndsWith(".pdf"))
            {
              content.Add(new JObject
              {
                ["type"] = "input_image",
                ["file_id"] = fileId,
                ["detail"] = "auto"
              });
            }
            else
            {
              content.Add(new JObject
              {
                ["type"] = "input_file",
                ["file_id"] = fileId,
                ["filename"] = name
              });
            }
          }
        }

        var body = new JObject
        {
            ["model"] = "{{foundry-model-deployment}}",
            ["max_output_tokens"] = int.Parse("{{foundry-max-output-tokens}}"),
            ["instructions"] = assistantInstructions + " Channel ID {{commerce-channel-id}}." + ((bool)context.Variables["anonymousCaller"] ? " The shopper is not signed in; use anonymous tool flows and ask for an email address only when a tool requires it." : string.Empty),
            ["tools"] = tools,
            ["input"] = new JArray
            {
                new JObject
                {
                    ["type"] = "message",
                    ["role"] = "user",
                  ["content"] = content
                }
            }
        };
        var previousResponseId = (string)context.Variables["previousResponseId"];
        if (!string.IsNullOrWhiteSpace(previousResponseId))
        {
            body["previous_response_id"] = previousResponseId;
        }

        return body.ToString();
    }

retry.interval:
@{
               var retryAfter = context.Response.Headers.GetValueOrDefault("Retry-After", "5");
               int retryAfterSeconds;
               return int.TryParse(retryAfter, out retryAfterSeconds)
                   ? Math.Min(Math.Max(retryAfterSeconds, 1), 60)
                   : 5;
           }
